# region imports
from AlgorithmImports import *
# endregion

class OrphanedTradeAlgorithm(QCAlgorithm):
    def initialize(self) -> None:
        self.set_start_date(2024, 9, 1)
        self.set_end_date(2024, 12, 31)
        self.set_cash(100000)

        # automatic_indicator_warm_up only supports automatic indicators, not manual indicators.
        self.settings.automatic_indicator_warm_up = True

        self._spy = self.add_equity("SPY", Resolution.MINUTE).symbol

        self._orb = self.orb(self._spy, 30)
        # Alternatively, use a manual indicator.
        # self._orb = OrphanedTradeIndicator(30)
        # self.warm_up_indicator(self._spy, self._orb)
        # self.register_indicator(self._spy, self._orb)

        self.plot_indicator("ORB", self._orb)

        self.schedule.on(
            self.date_rules.every_day(self._spy),
            self.time_rules.before_market_close(self._spy, 1),
            self._liquidate
        )

    def on_data(self, data: Slice) -> None:
        if not self._orb.is_ready:
            return

        buy_volume = self._orb.buy_volume.current.value
        sell_volume = self._orb.sell_volume.current.value

        if self.portfolio[self._spy].is_long:
            if sell_volume > buy_volume:
                self.liquidate(self._spy)
        elif self.portfolio[self._spy].is_short:
            if buy_volume > sell_volume:
                self.liquidate(self._spy)

    def _liquidate(self) -> None:
        if self.portfolio.invested:
            self.liquidate()

